using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using System.Text; using Mft.Application.Abstractions; using Mft.Application.Services; using Mft.Infrastructure; using Mft.Infrastructure.Persistence;
var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllers(); builder.Services.AddEndpointsApiExplorer(); builder.Services.AddSwaggerGen(); builder.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Default"))); builder.Services.AddScoped<IMftDbContext>(sp=>sp.GetRequiredService<AppDbContext>()); builder.Services.AddScoped<IMftService,MftService>(); builder.Services.AddScoped<IAuthService,AuthService>(); var key=Encoding.UTF8.GetBytes(builder.Configuration["Jwt:Key"]!); builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=false,ValidateAudience=false,ValidateLifetime=true,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(key)}); builder.Services.AddAuthorization(); builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyHeader().AllowAnyMethod().AllowAnyOrigin())); var app=builder.Build(); if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();} app.UseCors();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();